	@ParameterizedTest
	@CsvSource({ "completed-add,none", "completed-delete,none", "in-flight-add,none",
			"completed-add,blocked", "completed-delete,blocked", "in-flight-add,blocked", "in-flight-add,open",
			"retired-in-flight-add,open", "retired-rebuilt-in-flight-add,open",
			"configured-in-flight-add,open", "configured-rebuilt-in-flight-add,open" })
	void closeFencesAnUncommittedSourceUpdateAcrossReopen(String operation, String gate,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		Statement changed = statement("changed", 2);
		if (operation.equals("completed-delete")) {
			source.rows.add(changed);
		}
		SketchBasedJoinEstimator estimator = ready(source, directory);
		Files.copy(directory.resolve("synopsis-v8.bin"), directory.resolve("original-v8-backup.bin"));
		if (gate.equals("blocked")) {
			estimator.setRebuildAllowedSupplier(() -> false);
		} else if (gate.equals("open")) {
			estimator.setRebuildAllowedSupplier(() -> true);
		}
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Thread worker = null;
		boolean marked = false;
		try {
			if (operation.endsWith("in-flight-add")) {
				Statement blocked = new AbstractStatement() {
					@Override
					public Resource getSubject() {
						entered.countDown();
						try {
							if (!release.await(10, TimeUnit.SECONDS)) {
								throw new IllegalStateException("getter not released");
							}
						} catch (InterruptedException e) {
							Thread.currentThread().interrupt();
							throw new IllegalStateException(e);
						}
						return changed.getSubject();
					}

					@Override
					public IRI getPredicate() {
						return changed.getPredicate();
					}

					@Override
					public Value getObject() {
						return changed.getObject();
					}

					@Override
					public Resource getContext() {
						return changed.getContext();
					}
				};
				worker = new Thread(() -> {
					try {
						estimator.addStatement(blocked);
					} catch (Throwable problem) {
						failure.set(problem);
					}
				}, "close-fencing-in-flight-add");
				worker.start();
				assertTrue(entered.await(10, TimeUnit.SECONDS));
				if (operation.startsWith("retired")) {
					estimator.discardAndMarkForRebuild();
					if (operation.equals("retired-rebuilt-in-flight-add")) {
						assertTrue(estimator.forceFlush(), "a retired callback must not block a later rebuild");
					}
				} else if (operation.startsWith("configured")) {
					estimator.configurePersistence(directory, true);
					if (operation.equals("configured-rebuilt-in-flight-add")) {
						assertTrue(estimator.forceFlush(), "a reconfigured callback must not block a later rebuild");
					}
				}
			} else if (operation.equals("completed-add")) {
				estimator.addStatement(changed);
			} else {
				estimator.deleteStatement(changed);
			}
			estimator.close();
			marked = Files.exists(directory.resolve("synopsis-v8.rebuild"));
		} finally {
			if (operation.equals("completed-delete")) {
				source.rows.remove(changed);
			} else {
				source.rows.add(changed);
			}
			release.countDown();
			if (worker != null) {
				worker.join(TimeUnit.SECONDS.toMillis(10));
			}
			estimator.close();
		}
		if (worker != null) {
			assertFalse(worker.isAlive());
			assertEquals(null, failure.get());
		}
		assertTrue(marked, "close must fence a snapshot when the source might still lag");
		try (SketchBasedJoinEstimator reopened = newEstimator(source)) {
			reopened.configurePersistence(directory, true);
			assertFalse(reopened.isReadyNonBlocking(), "reopen cannot trust the old snapshot");
			assertTrue(reopened.forceFlush());
			assertEquals(operation.equals("completed-delete") ? 1.0d : 2.0d, predicateRows(reopened));
		}
	}

