	@ParameterizedTest
	@ValueSource(strings = { "discard", "configure" })
	void concurrentCompletionAndRetirementLeavesNoPhantomReservation(String retirement,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		Statement added = statement("second", 2);
		SketchBasedJoinEstimator estimator = ready(source, directory);
		Files.copy(directory.resolve("synopsis-v8.bin"), directory.resolve("original-v8-backup.bin"));
		estimator.setRebuildAllowedSupplier(() -> true);
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch retireReady = new CountDownLatch(1);
		CountDownLatch start = new CountDownLatch(1);
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Statement blocked = new AbstractStatement() {
			@Override
			public Resource getSubject() {
				entered.countDown();
				try {
					if (!start.await(10, TimeUnit.SECONDS)) {
						throw new IllegalStateException("race not released");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException(e);
				}
				return added.getSubject();
			}

			@Override
			public IRI getPredicate() {
				return added.getPredicate();
			}

			@Override
			public Value getObject() {
				return added.getObject();
			}

			@Override
			public Resource getContext() {
				return added.getContext();
			}
		};
		Thread worker = new Thread(() -> {
			try {
				estimator.addStatement(blocked);
			} catch (Throwable problem) {
				failure.compareAndSet(null, problem);
			}
		}, "close-concurrent-completion");
		Thread retirer = new Thread(() -> {
			retireReady.countDown();
			try {
				if (!start.await(10, TimeUnit.SECONDS)) {
					throw new IllegalStateException("race not released");
				}
				if (retirement.equals("discard")) {
					estimator.discardAndMarkForRebuild();
				} else {
					estimator.configurePersistence(directory, true);
				}
			} catch (Throwable problem) {
				failure.compareAndSet(null, problem);
			}
		}, "close-concurrent-retirement");
		worker.start();
		retirer.start();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS));
			assertTrue(retireReady.await(10, TimeUnit.SECONDS));
			start.countDown();
			worker.join(TimeUnit.SECONDS.toMillis(10));
			retirer.join(TimeUnit.SECONDS.toMillis(10));
			assertFalse(worker.isAlive());
			assertFalse(retirer.isAlive());
			assertEquals(null, failure.get());
			source.rows.add(added);
			assertTrue(estimator.forceFlush());
			estimator.close();
			assertFalse(Files.exists(directory.resolve("synopsis-v8.rebuild")));
			try (SketchBasedJoinEstimator reopened = newEstimator(source)) {
				reopened.configurePersistence(directory, true);
				assertTrue(reopened.isReadyNonBlocking());
				assertEquals(2.0d, predicateRows(reopened));
			}
		} finally {
			start.countDown();
			worker.join(TimeUnit.SECONDS.toMillis(10));
			retirer.join(TimeUnit.SECONDS.toMillis(10));
			estimator.close();
		}
	}

	@Test
	void cleanNonPersistentSynopsisEvictsAndRebuildsFromSource() {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		try (SketchBasedJoinEstimator estimator = newEstimator(source)) {
			estimator.rebuild();
			assertTrue(estimator.isReadyNonBlocking());
			var identity = estimator.quadSnapshotIdentity();
			long version = estimator.snapshotVersion();
			int scans = source.scans.get();
			assertTrue(estimator.allocatedBytes() > 0L);

			estimator.unload();

			assertEquals(0L, estimator.allocatedBytes(), "a clean nonpersistent synopsis must release its memory");
			assertFalse(estimator.isReadyNonBlocking());
			assertTrue(estimator.forceFlush(), "the source must rebuild an evicted nonpersistent synopsis");
			assertEquals(identity.storeIdHigh(), estimator.quadSnapshotIdentity().storeIdHigh());
			assertEquals(identity.storeIdLow(), estimator.quadSnapshotIdentity().storeIdLow());
			assertTrue(estimator.snapshotVersion() > version);
			assertEquals(1.0d, predicateRows(estimator));
			assertEquals(scans + 1, source.scans.get());
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void additionAfterNonPersistentEvictionWaitsForCurrentSource(boolean sourceUpdatedFirst) {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		Statement added = statement("added", 2);
		try (SketchBasedJoinEstimator estimator = newEstimator(source)) {
			estimator.rebuild();
			estimator.unload();
			assertEquals(0L, estimator.allocatedBytes());
			AtomicBoolean sourceCurrent = new AtomicBoolean(false);
			estimator.setRebuildAllowedSupplier(sourceCurrent::get);
			if (sourceUpdatedFirst) {
				source.rows.add(added);
			}
			estimator.addStatement(added);
			assertFalse(estimator.isReadyNonBlocking());
			assertFalse(estimator.forceFlush());
			if (!sourceUpdatedFirst) {
				source.rows.add(added);
			}
			sourceCurrent.set(true);
			assertTrue(estimator.forceFlush());
			assertEquals(2.0d, predicateRows(estimator), "the addition must be represented exactly once");
		}
	}

