	@Test
	void corruptSnapshotAfterUnloadRebuildsWithoutServingStaleEvidence(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		try (SketchBasedJoinEstimator estimator = ready(source, directory)) {
			Path snapshot = directory.resolve("synopsis-v8.bin");
			Files.copy(snapshot, directory.resolve("original-v8-backup.bin"));
			int scans = source.scans.get();
			estimator.unload();
			byte[] bytes = Files.readAllBytes(snapshot);
			bytes[bytes.length - Long.BYTES - 1] ^= 0x5a;
			Files.write(snapshot, bytes);
			assertTrue(estimator.forceFlush());
			assertEquals(1.0d, predicateRows(estimator));
			assertEquals(scans + 1, source.scans.get(), "a corrupt snapshot must rebuild from the source");
		}
	}

